        for j in range(cols):
            for k in range(i+1, rows+1):
                for l in range(j+1, cols+1):
                    curr_sum = sum([matrix[i][j], matrix[i][l], matrix[k][j], matrix[k][l]])
                    max_sum = max(max_sum, curr_sum)
    return max_sum

