def get_Min_Squares(num):
    if num <= 3:
        return num
    dp = [0] + [float('inf')]*num
    dp[1], dp[2], dp[3] = 1, 2, 3
    for i in range(4, num + 1):
        for j in range(1, i):
            if j*j > i:
                break
            dp[i] = min(dp[i], dp[i - j*j] + 1)
