    max_count = 0
    count = 0
    prev_char = ''
    for char in s:
        if char in vowels:
            if prev_char not in vowels:
                count += 1
            else:
                max_count = max(max_count, count)
                count = 1
        prev_char = char
    max_count = max(max_count, count)
