    maxgold = 0
    dr = [-1,0,1,0]
    dc = [0,1,0,-1]
    def isSafe(x,y):
        return 0<=x<r and 0<=y<c
    def dfs(x,y,gold,visited):
        nonlocal maxgold
        visited[x][y] = True
        for i in range(4):
            nx,ny = x+dr[i],y+dc[i]
            if isSafe(nx,ny) and not visited[nx][ny] and mine[nx][ny]>mine[x][y]:
                dfs(nx,ny,gold+mine[nx][ny],visited)
