def get_maxgold(mine, r, c):
    dp = [[0]*c for _ in range(r)]
    dp[0][0] = mine[0][0]
    for i in range(r):
        for j in range(c):
            if i-1 >= 0:
                dp[i][j] = max(dp[i][j], dp[i-1][j])
            if j-1 >= 0:
                dp[i][j] = max(dp[i][j], dp[i][j-1])
            if i-1 >= 0 and j-1 >= 0:
                dp[i][j] += mine[i][j]
    return dp[r-1][c-1]

