    subset = [[False for i in range(sub_sum + 1)] for j in range(n + 1)]

    for i in range(n + 1):
        subset[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, sub_sum + 1):
            if j < nums[i - 1]:
                subset[i][j] = subset[i - 1][j]
            if j >= nums[i - 1]:
                subset[i][j] = (subset[i - 1][j] or subset[i - 1][j - nums[i - 1]])

    return subset[n][sub_sum]

