def calculate_polygons(x1, y1, x2, y2, x3):
    def point_inside(x, y, x1, y1, x2, y2):
        if x < min(x1, x2) or x > max(x1, x2):
            return False
        if y < min(y1, y2):
            return False
        if y > max(y1, y2):
            return False
        return True

    def hexagon_coordinates(x, y, z, p1, p2, p3):
        s = (1/2) * (z + math.sqrt(3) * z)
        return [(x - s * math.cos(2 * math.pi * p1 / 6), y - s * math.sin(2 * math.pi * p1 / 6)) for p1, p2, p3 in zip(p1, p2, p3)]

    coordinates = [(x1, y1), (x2, y2), (x3, y3)]
    polygons = []

    for x, y in coordinates:
        if not any(point_inside(x, y, px, py, qx, qy) for px, py, qx, qy in zip(coordinates[:-1], coordinates[1:], coordinates)):
            continue
        hex_coords = hexagon_coordinates(x, y, 0, 0, 0, 0)
        polygons.append([(px, py) for px, py in zip(hex_coords, hex_coords[1:] + hex_coords[:1])])

    return polygons

