def heap_queue_smallest(nums, k):
    heap = nums[:k]
    heapq.heapify(heap)
    result = [heapq.heappop(heap)]
    for num in nums[k:]:
        if num < result[-1]:
            heapq.heappush(heap, num)
            result.append(heapq.heappop(heap))
        else:
            result.append(result[-1])
    return result

